    gap: clamp(28px, 4vw, 35px);
  }

  .dgs-footer-trust-badges {
    justify-content: center;
  }

  .dgs-footer-logo-column {
    grid-column: 1 / -1;
    max-width: 100%;
    text-align: center;
    align-items: center;
  }

  .dgs-footer-logo {
    margin-left: auto;
    margin-right: auto;
  }

  .dgs-footer-social {
    justify-content: center;
  }

  .dgs-footer-ai-summary {
    text-align: center;
  }

  .dgs-footer-ai-icons {
    justify-content: center;
  }
